  const currentTimestampField = React.useMemo(() => {
    try {
      const parsed = form.spec.trim() ? JSON.parse(form.spec) : {};
      return typeof parsed?.timestamp_field === 'string' ? parsed.timestamp_field : '';
    } catch {
      return '';
    }
  }, [form.spec]);

  const handleTimestampFieldChange = (val: string) => {
    setForm((prev) => {
      let parsed: Record<string, any> = {};
      try {
        const obj = prev.spec.trim() ? JSON.parse(prev.spec) : {};
        if (obj && typeof obj === 'object' && !Array.isArray(obj)) parsed = obj;
      } catch {
        parsed = {};
      }
      const trimmed = val.trim();
      if (trimmed) {
        parsed.timestamp_field = trimmed;
      } else {
        delete parsed.timestamp_field;
      }
      if (Array.isArray(parsed.shadow_sources) && prev.shadow_table) {
        parsed.shadow_sources = parsed.shadow_sources.map((s: any) =>
          s && s.shadow_table === prev.shadow_table
            ? { ...s, timestamp_field: trimmed || undefined }
            : s,
        );
      }
      return { ...prev, spec: JSON.stringify(parsed) };
    });
  };

